const goldenNames = readdirSync(GOLDEN_DIR)
  .filter(file => file.endsWith(GOLDEN_SUFFIX))
  .map(file => file.slice(0, -GOLDEN_SUFFIX.length))
  .sort();

describe('round trip', () => {
  it.each(VARIANTS)('parse(generate(x)).report is canonicalize(x): %s', (_, input, options) => {
    const { bytes } = generate1214(input, options);
    const { report, issues } = parse1214(bytes);
    expect(report).toEqual(canonicalize(input, options));
    expect(issues.filter(issue => issue.severity === 'error')).toEqual([]);
  });

  it('reports the provisional layout of a 2025 report on both sides of the round trip', () => {
    const input = minimalInput({ taxYear: 2025 });
    const { bytes, warnings } = generate1214(input, OPTIONS);
    const ruleIds = ['struct.taxYear.provisionalLayout'];
    expect(warnings.map(issue => issue.ruleId)).toEqual(ruleIds);
    expect(parse1214(bytes).issues.map(issue => issue.ruleId)).toEqual(ruleIds);
  });

  it('parses the generated text like the generated bytes', () => {
    const { text, bytes } = generate1214(minimalInput(), OPTIONS);
    expect(parse1214(text)).toEqual(parse1214(bytes));
  });

  it('has golden files to check', () => {
    expect(goldenNames.length).toBeGreaterThan(0);
  });

  it.each(goldenNames)('%s.opcn is regenerated byte for byte from its parsed report', name => {
    const golden = new Uint8Array(readFileSync(new URL(`${name}${GOLDEN_SUFFIX}`, GOLDEN_DIR)));
    const { report, saveDate, softwareName } = parse1214(golden);
    const { bytes } = generate1214({ ...report, meta: { saveDate, softwareName } });
    expect(Buffer.from(bytes).equals(Buffer.from(golden))).toBe(true);
  });

  it.each(goldenNames)('%s.opcn parses to the canonical form of its input', async name => {
    const { input, options } = (await import(new URL(`${name}.input.ts`, GOLDEN_DIR).href)) as {
      input: Report1214Input;
      options: GenerateOptions;
    };
    const golden = new Uint8Array(readFileSync(new URL(`${name}${GOLDEN_SUFFIX}`, GOLDEN_DIR)));
    expect(parse1214(golden).report).toEqual(canonicalize(input, options));
  });
});
